postconditions.probe:
map=$(git ls-files -z | tr '\0' '\n' | grep -E '(^|/)renames\.conf$' | head -n 1)
[ -n "$map" ] || exit 1
files=()
while IFS= read -r -d '' f; do
  [ -f "$f" ] && files+=("$f")
done < <(git ls-files --others --ignored --exclude-standard -z)
[ ${#files[@]} -gt 0 ] || exit 0
awk -v mapfile="$map" '
  BEGIN {
    while ((getline line < mapfile) > 0) {
      sub(/#.*/, "", line)
      eq = index(line, "=")
      if (eq == 0) continue
      old = substr(line, 1, eq - 1)
      gsub(/^[ \t]+|[ \t]+$/, "", old)
      if (old != "") oldset[old] = 1
    }
    close(mapfile)
  }
  {
    if (match($0, /^[ \t]*[^ \t=]+[ \t]*=/)) {
      key = substr($0, 1, RLENGTH)
      sub(/^[ \t]*/, "", key)
      sub(/[ \t]*=[ \t]*$/, "", key)
      if (key in oldset) { stale = 1; exit }
    }
  }
  END { exit (stale ? 1 : 0) }
' "${files[@]}"

